      "content": "{\n  \"name\": \"dsh-plugin-mac-notify\",\n  \"version\": \"1.0.0\",\n  \"description\": \"macOS Notification Center alerts when a DSH session finishes or needs you — the banner carries the last reply, plays your system alert sound, and clicking it jumps back to the DSH page\",\n  \"icon\": \"./icon.svg\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"author\": \"AK-blank\",\n  \"homepage\": \"https://github.com/AK-blank/dsh-plugin-mac-notify#readme\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AK-blank/dsh-plugin-mac-notify.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/AK-blank/dsh-plugin-mac-notify/issues\"\n  },\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./click\": \"./lib/click.mjs\",\n    \"./package.json\": \"./package.json\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"locale/*.json\",\n    \"icon.svg\",\n    \"selftest.mjs\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"LICENSE\"\n  ],\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"deepseek\",\n    \"cordis\",\n    \"cordis-plugin\",\n    \"host-plugin\",\n    \"macos\",\n    \"notification\",\n    \"terminal-notifier\",\n    \"notify\"\n  ],\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node selftest.mjs\",\n    \"selftest\": \"node selftest.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  }\n}\n"
